mapper.select:
select hlp_id as article_id, hlp_category as category, hlp_title as title, hlp_content as content, hlp_keywords as keywords, hlp_updated_at as updated_at from t_hlp_article where hlp_status = 1
and hlp_category = #{category}
and (hlp_title like concat('%', #{keyword}, '%') or hlp_category like concat('%', #{keyword}, '%') or hlp_keywords like concat('%', #{keyword}, '%') or hlp_content like concat('%', #{keyword}, '%'))
order by hlp_category asc, hlp_updated_at desc, hlp_id desc limit #{limit}

select count(1)
from t_fbk
where fbk_user_id = #{userId}
  and fbk_type = #{type}
  and fbk_subject = #{subject}
  and coalesce(fbk_description, '') = #{description}
  and fbk_created_at >= date_sub(now(), interval 1 minute)
